(* [comment removed for export] *)
#[using="Type"] Lemma art_int_alloc_fn : forall regs (M rom : word -> option byte) (raw : word) (sp : Z),
  getr regs 1 = raw -> ret_ok raw -> getr regs 2 = Z_to_bv 64 sp -> 48 <= sp -> sp < 2 ^ 64 -> 0x6b6000 + 48 <= sp ->
  wrA M (sp - 48) 48 -> cellA M 0x1ef508 1 1 ->
  msteps ASEGS (mkst regs (0x8c888 : word) M rom) (mkst (regupd (regupd (regupd (regupd (regupd (regupd (regupd regs 1 raw) 2 (Z_to_bv 64 sp)) 8 (getr regs 8)) 9 (getr regs 9)) 10 (Z_to_bv 64 0x160c80)) 18 (getr regs 18)) 19 (getr regs 19)) raw
