Definition art_drain_mem (M : word -> option byte) (sp : Z) (raw : word) (regs : bvmap 5 word) (c L F B bytes GL GB gbytes : Z) : word -> option byte :=
  let M2 := Wn 4 (art_drain_frame M sp raw regs) (0x15c6f0 + 152) 1 in
  let M3 := if GL =? 0 then Wn 8 (Wn 8 (Wn 8 M2 (0x15c6f0 + 176) B) (0x15c6f0 + 168) F) (0x15c6f0 + 160) L
            else Wn 8 (Wn 8 (Wn 8 M2 GB F) (0x15c6f0 + 160) (GL + L)) (0x15c6f0 + 176) B in
  Wn 1 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 M3 c 0) (c + 8) 0) (c + 16) 0) (0x15c6f0 + 184) (gbytes + bytes)) (c + 24) 0) (0x15c6f0 + 152) 0.

